import {
  Label,
  ProgressBar as AriaProgressBar,
} from "react-aria-components";
import type { ProgressBarProps as AriaProgressBarProps } from "react-aria-components";
import type { Ref } from "react";
import "./ProgressBar.css";

/** ProgressBar props shared by every naming shape (the React Aria value/range axis). */
export type ProgressBarBaseProps = Omit<AriaProgressBarProps, "className" | "children">;

/**
 * ProgressBar props.
 *
 * React Aria renders `role="progressbar"`, which **requires an accessible name** (WCAG 4.1.2 —
 * axe: `aria-progressbar-name`). So the name is mandatory at the type level: pass a visible
 * `label`, or — when the bar is named by neighbouring content — `aria-label` /
 * `aria-labelledby`. Omitting all three does not compile.
 * (The contract's only sanctioned discriminated-union shape — component-contract.md §2,
 * same pattern as Button's `isIconOnly`.)
 */
export type ProgressBarProps = ProgressBarBaseProps & {
  /**
   * Bar thickness. `small` is the thin rule a flow step runs under its header (on the line-thickness
   * scale, square-ended); `medium` is the default capsule. The label and value follow it.
   *
   * Square ends belong to `small` because at a line's thickness the capsule's radius is a pixel or
   * two: no longer a shape, only a blunted leading edge on the fill. Running it edge to edge is the
   * consumer's layout (a `100cqi` wrapper, as `Band` does), never this component's.
   *
   * @default "medium"
   */
  size?: "small" | "medium";
  /**
   * Show the formatted value beside the label.
   *
   * React Aria already computes it — `valueText` (`valueLabel` when given, else the value run
   * through `formatOptions`, which defaults to `{ style: "percent" }`) — and exposes it as a
   * render prop **and** as `aria-valuetext`. Without this the value reaches assistive tech only,
   * so a sighted reader sees an unlabelled bar. Off by default: a bar used as pure decoration
   * beside its own copy (an upload row, a step indicator) should not repeat the number.
   * An **indeterminate** bar has no value, so nothing renders even when this is on.
   */
  showValue?: boolean;
} & (
    | { label: string }
    | { label?: undefined; "aria-label": string }
    | { label?: undefined; "aria-labelledby": string }
  ) & {
    /** Additional class. sd-progress-bar is always retained. */
    className?: string;
    /** Passed to the root progress bar DOM element. */
    ref?: Ref<HTMLDivElement>;
  };

/**
 * ProgressBar — **one operation advancing over time** (an upload, a wizard, a task list).
 *
 * **ProgressBar or Meter?** A progress bar appears, advances toward completion, and goes away;
 * 95% there just means "nearly done", with no good/bad to it. A `Meter` is a **standing reading
 * within a known range** that persists, moves both ways, and whose value does carry a quality
 * (disk used, battery, rating distribution). The test: *does it end and disappear?* →
 * `ProgressBar`. *Is it a standing value that can go up or down?* → `Meter`. Two consequences
 * follow, and they are the only differences in what the two can express (a `size` is look, not meaning): only this component can be
 * **indeterminate** (an operation of unknown duration), and it deliberately has **no `variant`** —
 * progress has no valence to colour.
 *
 * @usageInvariant meter-progressbar-axes
 */
export function ProgressBar({
  size = "medium",
  showValue = false,
  label,
  value,
  minValue = 0,
  maxValue = 100,
  isIndeterminate,
  className,
  ref,
  ...props
}: ProgressBarProps) {
  return (
    <AriaProgressBar
      {...props}
      ref={ref}
      value={value}
      minValue={minValue}
      maxValue={maxValue}
      isIndeterminate={isIndeterminate}
      data-size={size}
      className={className ? `sd-progress-bar ${className}` : "sd-progress-bar"}
    >
      {/* Borrow React Aria's own clamped percentage — don't recompute by hand. */}
      {({ percentage, valueText, isIndeterminate: indeterminate }) => {
        // The label/value row only exists when it has something in it — an always-rendered
        // header would add its own gap above a bare track. `valueText` is undefined while
        // indeterminate, so an indeterminate bar shows no value even with showValue on.
        // NOT named `value` — that is the numeric prop destructured above, and shadowing it here
        // would silently hand a formatted string to any later edit that reaches for it.
        const shownValue = showValue ? valueText : undefined;
        return (
          <>
            {(label || shownValue) && (
              <div className="sd-progress-bar__header">
                {label && (
                  <Label className={`sd-progress-bar__label sd-type-label-${size}`}>{label}</Label>
                )}
                {/* Decorative on purpose: this span is a VISUAL MIRROR of `aria-valuetext`
                    (literally the same string — React Aria feeds the render prop from that very
                    attribute), so assistive tech already has the value from the bar itself.
                    Leaving it exposed risks announcing the number twice, the same double-read
                    `Spinner`'s `isDecorative` and `Skeleton`'s always-hidden contract exist to
                    prevent. Verified against the CDP accessibility tree. */}
                {shownValue && (
                  <span
                    aria-hidden="true"
                    className={`sd-progress-bar__value sd-type-body-${size}`}
                  >
                    {shownValue}
                  </span>
                )}
              </div>
            )}
            <div data-size={size} className="sd-progress-bar__track">
              <div
                data-indeterminate={indeterminate || undefined}
                data-size={size}
                className="sd-progress-bar__fill"
                style={{ width: indeterminate ? undefined : `${percentage ?? 0}%` }}
              />
            </div>
          </>
        );
      }}
    </AriaProgressBar>
  );
}

.sd-progress-bar {
  display: flex;
  flex-direction: column;
  gap: var(--sd-progress-bar-gap);
  width: var(--sd-progress-bar-width);
}

/* Label left, value right, on one baseline — the label may wrap, the value never shrinks. */
.sd-progress-bar__header {
  display: flex;
  align-items: baseline;
  gap: var(--sd-progress-bar-header-gap);
}

.sd-progress-bar__label {
  color: var(--sd-progress-bar-label-foreground);
}

/* `margin-inline-start: auto` rather than `justify-content: space-between` on the row: the two
   agree while both parts render, but space-between falls back to flex-start when the value is
   the ONLY item (no visible label), which moves the value out of its slot. These are positional
   slots — stack several bars and every value must line up whether or not each has a label. */
.sd-progress-bar__value {
  /* A value that changes in place (a count, a percentage) keeps its width, so it does not jitter as
     its digits change. */
  font-variant-numeric: tabular-nums;
  flex: 0 0 auto;
  margin-inline-start: auto;
  color: var(--sd-progress-bar-value-foreground);
}

.sd-progress-bar__track {
  overflow: hidden;
  height: var(--sd-progress-bar-track-height);
  background: var(--sd-progress-bar-track-background);
  border-radius: var(--sd-progress-bar-track-radius);
  corner-shape: round;
}

.sd-progress-bar__fill {
  width: 0;
  height: 100%;
  background: var(--sd-progress-bar-fill-background);
  border-radius: var(--sd-progress-bar-fill-radius);
  corner-shape: round;
  transition: width var(--sd-duration-slow) var(--sd-easing-standard);
}

/* small: a rule, not a capsule. At a line's thickness `radius.full` is a pixel or two, which no longer
   reads as a round end, only blunts the fill's leading edge, so both parts square off. 0 rather than a
   token, since no radius rung means "none" (TextField's underline does the same). */
.sd-progress-bar__track[data-size="small"] {
  height: var(--sd-progress-bar-track-height-small);
  border-radius: 0;
}

.sd-progress-bar__fill[data-size="small"] {
  border-radius: 0;
}

.sd-progress-bar__fill[data-indeterminate] {
  width: var(--sd-progress-bar-fill-width-indeterminate);
  background:
    linear-gradient(
      90deg,
      transparent,
      var(--sd-progress-bar-fill-background),
      transparent
    );
  animation: sd-progress-bar-indeterminate var(--sd-progress-bar-animation-duration) ease-in-out infinite;
}

@keyframes sd-progress-bar-indeterminate {
  from {
    transform: translateX(var(--sd-progress-bar-fill-translate-start-indeterminate));
  }
  to {
    transform: translateX(var(--sd-progress-bar-fill-translate-end-indeterminate));
  }
}

@media (prefers-reduced-motion: reduce) {
  .sd-progress-bar__fill {
    transition: none;
  }

  /* No sliding sweep, but keep a motion-safe activity cue: a full-width bar with
     a gentle opacity pulse, so indeterminate still reads as "in progress" rather
     than a stalled determinate bar frozen at ~45%. */
  .sd-progress-bar__fill[data-indeterminate] {
    width: 100%;
    background: var(--sd-progress-bar-fill-background);
    transform: none;
    animation: sd-progress-bar-indeterminate-pulse var(--sd-progress-bar-animation-duration) ease-in-out infinite;
  }
}

@keyframes sd-progress-bar-indeterminate-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}
